use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";
const SUBSCRIPTIONS_KEY: &str = "urls";

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

/// Parse a JSON array of strings. Returns None if the input is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let s = s.trim();
    let inner = s.strip_prefix('[')?.strip_suffix(']')?;
    let mut out = Vec::new();
    let mut chars = inner.chars().peekable();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace() || *c == ',') {
            chars.next();
        }
        match chars.next() {
            None => break,
            Some('"') => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                            other => cur.push(other),
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            Some(_) => return None,
        }
    }
    Some(out)
}

fn parse_urls(raw: &str) -> Vec<String> {
    let list = parse_json_string_array(raw).unwrap_or_else(|| {
        raw.split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect()
    });
    list.into_iter()
        .map(|u| u.trim().to_string())
        .filter(|u| !u.is_empty() && !u.starts_with('#'))
        .collect()
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (approved extension). Transport failures come back as
        // values and are ignored; the output does not depend on the result.
        let enrich_url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        let urls = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => parse_urls(&raw),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
